// TH14 synthetic alias table subset; source type4 -> target slot 416 (same number).
// See transcribe/th14/touhou-bullets.ecl and bullet-types.md.
const TH14_BALL: int = 416;

// TH14 v1.00b Stage 4 wave. Source: st04.ecl.txt:1052-1062 (MainSub01 entry),
// deps ECir01 158-191 and ECir01_at 193-274. Card frame 0 starts the segment timer;
// the source wave begins after the 120-frame opening buffer.

const TIME_LIMIT: int = 1924;
const OPENING_BUFFER: int = 120;

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

async sub wave() {
    wait(OPENING_BUFFER);
    // Source 1054-1060: four creates at source t=0/110/210/290, y=64/48/32/16,
    // MIRROR=1/0/1/0. dir is the source %A sign (mirrored -> -1).
    _ = spawn_enemy(0fx, 64fx, 150, 0, 0, 0, ecir(-1fx));
    wait(110);
    _ = spawn_enemy(0fx, 48fx, 150, 0, 0, 0, ecir(1fx));
    wait(100);
    _ = spawn_enemy(0fx, 32fx, 150, 0, 0, 0, ecir(-1fx));
    wait(80);
    _ = spawn_enemy(0fx, 16fx, 150, 0, 0, 0, ecir(1fx));
}

async sub ecir(dir: fx) {
    set_invuln(65535);
    set_hurtbox(12fx);   // source 167 setHurtbox(24,24): radius 24*0.5
    set_hitbox(8fx);     // source 168 setHitbox(16,16): radius 16*0.5
    // Source 169-177 drops / flagSet(15) / entrance ANM omitted (approved policy).
    var y0: fx = $self_y;
    // Source 178 movePosRel(-192*A,0): REL layer; ABS stays at birth (x=0,y0).
    var sx: fx = -192fx * dir;
    move_to(0, sx, y0, EASE_LINEAR);
    // Source 179 moveBezierRel(120, (256A,-30), (160A,128), (0,0)):
    // REL target is the value (160A,128), world = ABS + REL.
    var x1: fx = 160fx * dir;
    var y1: fx = y0 + 128fx;
    hermite_start(0, sx, x1, 256fx * dir, 0fx, 120);
    hermite_start(1, y0, y1, -30fx, 0fx, 120);
    for i in 0..120 {
        wait(1);
        move_to(0, hermite_value(0), hermite_value(1), EASE_LINEAR);
    }
    // Source 181-184: flagClear(15)/ANM restore omitted; second bezier + async attack.
    // Source 183 moveBezierRel(120, (0,0), (-220A,192), (-200A,-228)).
    var x2: fx = -220fx * dir;
    var y2: fx = y1 + 64fx;
    spawn ecir_at();
    hermite_start(0, x1, x2, 0fx, -200fx * dir, 120);
    hermite_start(1, y1, y2, 0fx, -228fx, 120);
    for k in 0..120 {
        wait(1);
        move_to(0, hermite_value(0), hermite_value(1), EASE_LINEAR);
    }
    // Source 185-189: main context waits forever; enemy stays until out of play.
    loop { wait(1000); }
}

async sub ecir_at() {
    var rank: int = global(GVAR_RANK);
    // Source 196-205: first laser delay E10 N10 H0 L0.
    var d0: int = 10;
    if rank >= RANK_HARD { d0 = 0; }
    wait(d0);
    // Source 238 diffI C = E1 N1 H2 L5; 242 diffI D = E3 N5 H5 L7;
    // 247 diffF B = E30 N22.5 H22.5 L18 deg; 209-235 speed/length; 261-269 cycle gap.
    var c: int = 1;
    if rank == RANK_HARD { c = 2; }
    if rank == RANK_LUNATIC { c = 5; }
    var d: int = 3;
    if rank >= RANK_NORMAL { d = 5; }
    if rank == RANK_LUNATIC { d = 7; }
    var astep: angle = 5461bam;                    // 30 deg
    if rank >= RANK_NORMAL { astep = 4096bam; }    // 22.5 deg
    if rank == RANK_LUNATIC { astep = 3277bam; }   // 18 deg
    var lspd: fx = 2.7fx;
    if rank >= RANK_NORMAL { lspd = 4fx; }
    if rank == RANK_LUNATIC { lspd = 5fx; }
    var llen: fx = 128fx;
    if rank == RANK_NORMAL { llen = 160fx; }
    if rank == RANK_HARD { llen = 144fx; }
    if rank == RANK_LUNATIC { llen = 160fx; }
    var gap: int = 60;
    if rank == RANK_NORMAL { gap = 50; }
    if rank == RANK_HARD { gap = 20; }
    if rank == RANK_LUNATIC { gap = 10; }
    for cyc in 0..c {
        var a: angle = 8192bam;   // source 241: A = 0.785398 (45 deg)
        for j in 0..d {
            // Source 245-246: etAngle(ANGLE_PLAYER + A) then laserOn(0).
            // Line judgment: constant-width rod of 0.8*L (laser_approx) growing at et speed.
            var lz: int = laser(3, $self_x, $self_y, aim_player() + a, 0fx, 7fx, 0, 9999, 0);
            lz_speed(lz, lspd, 0.8fx * llen);
            a = a - astep;        // source 248: A = A - B
        }
        if rank >= RANK_NORMAL {
            // Source 252-259: etAim(1,8), 8 ways: per-bullet random angle then speed,
            // alpha = ANGLE_PLAYER-15deg, delta = 30deg, speed = 1+2*U.
            for b in 0..8 {
                var ra: int = rand(65536);
                var su: fx = (ra - 32768) as fx / 32768;
                var off: int = (5461fx * su) as int;
                var ba: angle = aim_player() - 2731bam + (off as angle);
                var rv: int = rand(65536);
                var u: fx = (rv - 32768) as fx / 65536 + 0.5fx;
                var sp: fx = 1fx + u * 2fx;
                // Source 258 etEx type2 (ANIM): spawn retreat position -= 4*velocity
                // (birth animation/waits themselves omitted by policy).
                _ = fire(TH14_BALL, 8,
                         $self_x - 4fx * sp * cos(ba),
                         $self_y - 4fx * sp * sin(ba),
                         sp, ba, none, none);
            }
        }
        wait(gap);
    }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
